    "maxWorkers": {
      "type": "number",
      "title": "Max parallel workers",
      "description": "Most implementer and reader tasks harness_run starts at once.",
      "default": 3
    },
    "autoRun": {
      "type": "boolean",
      "title": "Run tasks automatically",
      "description": "harness_plan starts every ready task and each finished task starts the next ready ones.",
      "default": true
    },
    "scopeMode": {
      "type": "string",
      "title": "Scope mode",
      "description": "off, report or enforce. enforce hides skills and agents the harness did not select for the task; report only computes the receipt.",
